From 48e3cbc45f1434260bc7cdf0139688749113ee05 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:31:51 +0100
Subject: [PATCH] applet: find the access point again if a scan replaced it

A scan while the password was being typed could replace the access
point, so the applet sent its old path and NetworkManager refused it as
not in the scan list. Now it also passes the SSID to find the new one.

BUG: 495706
---
 applet/ConnectionItem.qml |  4 ++--
 libs/handler.cpp          | 19 ++++++++++++++-----
 libs/handler.h            |  5 +++--
 3 files changed, 19 insertions(+), 9 deletions(-)

diff --git a/applet/ConnectionItem.qml b/applet/ConnectionItem.qml
index e2a79fd2f..1fb22d98c 100644
--- a/applet/ConnectionItem.qml
+++ b/applet/ConnectionItem.qml
@@ -278,11 +278,11 @@ PlasmaExtras.ExpandableListItem {
         if (model.Uuid || !predictableWirelessPassword || connectionItem.customExpandedViewContent == passwordDialogComponent) {
             if (model.ConnectionState == PlasmaNM.Enums.Deactivated) {
                 if (!predictableWirelessPassword && !model.Uuid) {
-                    handler.addAndActivateConnection(model.DevicePath, model.SpecificPath)
+                    handler.addAndActivateConnection(model.DevicePath, model.SpecificPath, "", model.Ssid)
                 } else if (connectionItem.customExpandedViewContent == passwordDialogComponent) {
                     const item = connectionItem.customExpandedViewContentItem;
                     if (item && item.password !== "") {
-                        handler.addAndActivateConnection(model.DevicePath, model.SpecificPath, item.password)
+                        handler.addAndActivateConnection(model.DevicePath, model.SpecificPath, item.password, model.Ssid)
                         connectionItem.customExpandedViewContent = detailsComponent
                         connectionItem.collapse()
                     } else {
diff --git a/libs/handler.cpp b/libs/handler.cpp
index 1a8d79746..9a531d047 100644
--- a/libs/handler.cpp
+++ b/libs/handler.cpp
@@ -269,22 +269,29 @@ void Handler::requestWifiCode(const QString &connectionPath, const QString &ssid
     });
 }

-void Handler::addAndActivateConnection(const QString &device, const QString &specificParameter, const QString &password)
+void Handler::addAndActivateConnection(const QString &device, const QString &specificParameter, const QString &password, const QString &ssid)
 {
-    addAndActivateConnectionInternal(device, specificParameter, password);
+    addAndActivateConnectionInternal(device, specificParameter, password, ssid);
 }

-QCoro::Task<> Handler::addAndActivateConnectionInternal(const QString &device, const QString &specificObject, const QString &password)
+QCoro::Task<> Handler::addAndActivateConnectionInternal(const QString &device, const QString &specificParameter, const QString &password, const QString &ssid)
 {
     NetworkManager::AccessPoint::Ptr ap;
     NetworkManager::WirelessDevice::Ptr wifiDev;
     for (const NetworkManager::Device::Ptr &dev : NetworkManager::networkInterfaces()) {
         if (dev->type() == NetworkManager::Device::Wifi) {
             wifiDev = dev.objectCast<NetworkManager::WirelessDevice>();
-            ap = wifiDev->findAccessPoint(specificObject);
-            if (ap) {
+            if (wifiDev->accessPoints().contains(specificParameter)) {
+                ap = wifiDev->findAccessPoint(specificParameter);
                 break;
             }
+            // A new scan may have replaced the access point since the caller got its path
+            if (!ssid.isEmpty() && dev->uni() == device) {
+                if (NetworkManager::WirelessNetwork::Ptr network = wifiDev->findNetwork(ssid)) {
+                    ap = network->referenceAccessPoint();
+                    break;
+                }
+            }
         }
     }

@@ -292,6 +299,8 @@ QCoro::Task<> Handler::addAndActivateConnectionInternal(const QString &device, c
         co_return;
     }

+    const QString specificObject = ap->uni();
+
     NetworkManager::ConnectionSettings::Ptr settings =
         NetworkManager::ConnectionSettings::Ptr(new NetworkManager::ConnectionSettings(NetworkManager::ConnectionSettings::Wireless));
     settings->setId(ap->ssid());
diff --git a/libs/handler.h b/libs/handler.h
index 64a8425de..f60adef45 100644
--- a/libs/handler.h
+++ b/libs/handler.h
@@ -76,7 +76,8 @@ public Q_SLOTS:
      * Works automatically for wireless connections with WEP/WPA security, for wireless connections with WPA/WPA
      * it will open the connection editor for advanced configuration.
      * */
-    void addAndActivateConnection(const QString &device, const QString &specificParameter, const QString &password = QString());
+    void
+    addAndActivateConnection(const QString &device, const QString &specificParameter, const QString &password = QString(), const QString &ssid = QString());

     /**
      * Request a code that includes the credentials to a said wifi connection
@@ -147,7 +148,7 @@ Q_SIGNALS:
 private:
     QCoro::Task<> addAndActivateConnectionDBus(const NMVariantMapMap &map, const QString &device, const QString &specificObject);
     QCoro::Task<> activateConnectionInternal(const QString &connection, const QString &device, const QString &specificParameter);
-    QCoro::Task<> addAndActivateConnectionInternal(const QString &device, const QString &specificParameter, const QString &password = QString());
+    QCoro::Task<> addAndActivateConnectionInternal(const QString &device, const QString &specificParameter, const QString &password, const QString &ssid);
     QCoro::Task<> deactivateConnectionInternal(const QString &connection, const QString &device);
     QCoro::Task<> removeConnectionInternal(const QString &connection);
     QCoro::Task<> requestScanInternal(const QString &interface = QString());
-- 
